use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        let n1 = if parts.len() > 1 { parts[1] } else { "" }
        let n2 = if parts.len() > 2 { parts[2] } else { "" }
        if cmd == "open" && parts.len() >= 3 {
            let amt: int = n2.parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(n1) {
                println("error: duplicate account")
            } else {
                acc.insert(n1, amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && parts.len() >= 3 {
            let amt: int = n2.parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(n1) {
                println("error: unknown account ${n1}")
            } else {
                let bal: int = acc.get(n1) ?? 0
                if cmd == "deposit" {
                    acc.insert(n1, bal + amt)
                    println("ok")
                } else if bal < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(n1, bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && parts.len() >= 4 {
            let n3 = parts[3]
            let amt: int = n3.parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(n1) {
                println("error: unknown account ${n1}")
            } else if !acc.contains_key(n2) {
                println("error: unknown account ${n2}")
            } else if n1 == n2 {
                println("error: same account")
            } else {
                let a: int = acc.get(n1) ?? 0
                let b: int = acc.get(n2) ?? 0
                if a < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(n1, a - amt)
                    acc.insert(n2, b + amt)
                    println("ok")
                }
            }
        } else if cmd == "balance" && parts.len() >= 2 {
            if !acc.contains_key(n1) {
                println("error: unknown account ${n1}")
            } else {
                let b: int = acc.get(n1) ?? 0
                println("${b}")
            }
        }
    }
    let mut keys: Vec<string> = acc.keys().map(|k| k.to_string()).collect()
    keys.sort()
    for k in keys {
        let b: int = acc.get(k) ?? 0
        println("${k} ${b}")
    }
}

