use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0].clone()
        if cmd == "open" && parts.len() >= 3 {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(&parts[1]) {
                println("error: duplicate account")
            } else {
                acc.insert(parts[1].clone(), amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && parts.len() >= 3 {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(&parts[1]) {
                println("error: unknown account ${parts[1]}")
            } else {
                let bal: int = *acc.get(&parts[1]).unwrap()
                if cmd == "deposit" {
                    acc.insert(parts[1].clone(), bal + amt)
                    println("ok")
                } else if bal < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(parts[1].clone(), bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && parts.len() >= 4 {
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(&parts[1]) {
                println("error: unknown account ${parts[1]}")
            } else if !acc.contains_key(&parts[2]) {
                println("error: unknown account ${parts[2]}")
            } else if parts[1] == parts[2] {
                println("error: same account")
            } else {
                let a: int = *acc.get(&parts[1]).unwrap()
                let b: int = *acc.get(&parts[2]).unwrap()
                if a < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(parts[1].clone(), a - amt)
                    acc.insert(parts[2].clone(), b + amt)
                    println("ok")
                }
            }
        } else if cmd == "balance" && parts.len() >= 2 {
            if !acc.contains_key(&parts[1]) {
                println("error: unknown account ${parts[1]}")
            } else {
                println("${*acc.get(&parts[1]).unwrap()}")
            }
        }
    }
    let mut keys: Vec<string> = acc.keys().map(|k| k.clone()).collect()
    keys.sort()
    for k in keys {
        println("${k} ${*acc.get(&k).unwrap()}")
    }
}
